mapper.select:
SELECT h.id AS hospitalId, h.name AS name, h.city AS city, h.district AS district, h.level AS level, h.address AS address, h.booking_url AS bookingUrl, hd.department AS department, hd.specialty_level AS specialtyLevel, COALESCE(hd.source_url, h.source_url) AS sourceUrl, (hd.source_url IS NOT NULL AND hd.verified_at IS NOT NULL) AS verified FROM hospital h JOIN hospital_department hd ON hd.hospital_id = h.id WHERE h.status = 1
AND h.city = #{city}
AND hd.department = #{department}
ORDER BY (hd.specialty_level IS NULL), hd.specialty_level DESC, h.id LIMIT #{limit}
